  history: Array<{ version: number; snapshot: Partial<Task>; updatedAt: Date; feedback: string }>;
}

async function refineTask(id: string, feedback: string, changes: Partial<Task>): Promise<Task> {
  const tasks = await loadTasks();
  const taskIndex = tasks.findIndex(t => t.id === id);
  if (taskIndex === -1) throw new Error('Task not found');
  const task = tasks[taskIndex];
  // Validate, e.g., if (task.status === 'completed' && !changes.status) throw...
  const version = (task.history?.length || 0) + 1;
  task.history = [...(task.history || []), { version, snapshot: structuredClone(task), updatedAt: new Date(), feedback }];
  Object.assign(task, changes);
  tasks[taskIndex] = task;
  await saveTasks(tasks);
  return task;
}

